"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Η Καστάμονου υπό την κυριαρχία των Τσομπανογουλλαρί — χρονολογημένη μαρτυρία της πηγής", "10b682ba"], "d": ["Η πηγή εμφανίζει την πόλη της Καστάμονου υπό τη διοίκηση των Τσομπανογουλλαρί αυτή την ημερομηνία· η προηγούμενη κυριότητα δεν χρονολογείται στην πηγή (ο άτλας αφήνει κενό το διάστημα πριν από αυτή την ημερομηνία).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Ο Α΄ Ιζεντίν Κεϊκαβούς κατέκτησε τη Σινώπη", "463ea2b9"], "d": ["Ο Σελτζούκος σουλτάνος Α΄ Ιζεντίν Κεϊκαβούς πήρε τη Σινώπη από τους Κομνηνούς της Τραπεζούντας.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Ο Α΄ Αλαεντίν Κεϊκουμπάντ κατέλαβε το Καλονόρος (Αλάγια)", "5a4d6ac2"], "d": ["Το κάστρο Καλονόρος, ανατολικά της Αττάλειας, καταλήφθηκε από τους Σελτζούκους, ανοικοδομήθηκε και πήρε το όνομα Αλάγια (το λήμμα «Αλάγια» αναφέρει το 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Ο Τζελαλεντίν Χαρεζμσάχ προσάρτησε το Αζερμπαϊτζάν", "5b812b99"], "d": ["Ο Τζελαλεντίν Χαρεζμσάχ προσάρτησε στα εδάφη του το Αζερμπαϊτζάν και το Άρραν (περιφερειακή πρόταση).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Ο Τζελαλεντίν Χαρεζμσάχ κατέλαβε τη Μεράγα", "a55ec004"], "d": ["Ο Τζελαλεντίν Χαρεζμσάχ κατέλαβε τη Μεράγα και την έκανε στρατιωτικό και διοικητικό κέντρο στο Αζερμπαϊτζάν.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Ο Τζελαλεντίν Χαρεζμσάχ μπήκε στην Τεβρίζ", "72904097"], "d": ["Όταν ο ατεμπέγκης Ουζμπέκ αποσύρθηκε στη Γκιάντζα, ο Τζελαλεντίν Χαρεζμσάχ μπήκε στην Τεβρίζ, κυριάρχησε στην πόλη και την έκανε κέντρο του.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Ο Αλαεντίν Κεϊκουμπάντ κατέλαβε την Κεμάχ", "8c5aa655"], "d": ["Ο κλάδος Κεμάχ-Ερζιντζάν των Μενγκουτσεκιδών προσαρτήθηκε στα εδάφη των Σελτζούκων από τον Α΄ Αλαεντίν Κεϊκουμπάντ, ο οποίος πολιόρκησε και κατέλαβε την Κεμάχ.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Η Μεράγα καταλήφθηκε για δεύτερη φορά από τους Μογγόλους", "f1320e5d"], "d": ["Με το τέλος της κυριαρχίας των Χαρεζμσάχ, η Μεράγα πέρασε στα χέρια των Μογγόλων.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Το Αζερμπαϊτζάν πέρασε στη μογγολική κυριαρχία — η Τεβρίζ υπέστη μογγολική κατοχή", "3f38ef66"], "d": ["Με την κατάρρευση του Τζελαλεντίν Χαρεζμσάχ, η Τεβρίζ υπέστη το 1231 μογγολική κατοχή· η μογγολική κυριαρχία κάλυψε την ίδια χρονιά το Βόρειο και το Νότιο Αζερμπαϊτζάν (περιφερειακή πρόταση, όχι ειδική για την πόλη). Στη Σιρβάν (Μπακού, Σαμαχί) οι Σιρβανσάχ συνέχισαν να υπάρχουν ως τοπική δυναστεία υπό μογγολική κυριαρχία· ο άτλας διατηρεί αυτά τα δύο σημεία στο χρώμα των Σιρβανσάχ με απόφαση του Εμρέ (η υποτέλεια στους Μογγόλους/Ιλχανίδες αναφέρεται στη σημείωση).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["Ο Αγιουβίδης ελ-Μελίκ ελ-Καμίλ κατέλαβε την Άμιντ", "9cebe681"], "d": ["Ο ελ-Μελίκ ελ-Καμίλ πολιόρκησε την Άμιντ και την πήρε από τους Αρτουκίδες.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Ο Α΄ Αλαεντίν Κεϊκουμπάντ πήρε την Κιουτάχεια από την Αυτοκρατορία της Νίκαιας", "e0b9a7f7"], "d": ["Η Κιουτάχεια, που είχε περάσει ξανά στους Βυζαντινούς στις αναταραχές μετά το 1182, αφαιρέθηκε και πάλι από την Αυτοκρατορία της Νίκαιας επί Α΄ Αλαεντίν Κεϊκουμπάντ.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Ο Μπεντρεντίν Λουλού σουλτάνος της Μοσούλης", "73268628"], "d": ["Με τον θάνατο του τελευταίου Ζενγκίδη ατεμπέγκη, ο Μπεντρεντίν Λουλού ανακηρύχθηκε σουλτάνος από τον χαλίφη. (Ρεμπιουλεβέλ 631 / Δεκέμβριος 1233· ο άτλας, ακολουθώντας την εγγραφή του κράτους, το γράφει με ακρίβεια έτους.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Οι Σελτζούκοι κατέλαβαν το Χαρπούτ", "3b9391eb"], "d": ["Ο στρατός του Αλαεντίν Κεϊκουμπάντ παρέλαβε το κάστρο του Χαρπούτ έπειτα από εικοσιτετραήμερη πολιορκία· οι Αρτουκίδες του Χαρπούτ έπαυσαν να υπάρχουν.", "1ae6c0d9"]},
