"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Ο Μενγκού Καγάν διόρισε τον Ιφτιχαρεντίν διοικητή της Καζβίν", "fc650d13"], "d": ["Ο Μέγας Χαν των Μογγόλων Μενγκού διόρισε διοικητή στην Καζβίν· ξεκίνησε η περίοδος των Ιφτιχαριδών.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Η άφιξη του Χουλαγκού: η Καζβίν και το Ναχτσιβάν πέρασαν στη διοίκηση των Ιλχανιδών", "24673608"], "d": ["Με την άφιξη του Χουλαγκού στο Ιράν, η μογγολική διοίκηση πέρασε στο Κράτος των Ιλχανιδών· η Καζβίν και το Ναχτσιβάν πέρασαν στη διοίκηση των Ιλχανιδών (όριο του κανόνα 5, όχι ημέρα της πηγής). Στη Σιρβάν (Μπακού, Σαμαχί) η μογγολική εισβολή έφερε βαριά καταστροφή, αλλά οι Σιρβανσάχ συνέχισαν ως τοπική δυναστεία· ο άτλας διατηρεί αυτά τα δύο σημεία στο χρώμα των Σιρβανσάχ (απόφαση του Εμρέ).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Οι Μογγόλοι κατέλαβαν το Τικρίτ", "60af2df0"], "d": ["Κατά τη μογγολική εισβολή το Τικρίτ καταλήφθηκε και λεηλατήθηκε· η πόλη βγήκε από τη διοίκηση των Αββασιδών.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Ο Χουλαγκού βάδισε από το Χαμαντάν προς τη Βαγδάτη", "5f0c77b5"], "d": ["Ο Χουλαγκού ξεκίνησε εκστρατεία προς τη Βαγδάτη από το Χαμαντάν, όπου βρίσκονταν τα βαριά του φορτία (μαρτυρία της ιλχανιδικής κυριαρχίας).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Ο Μπογκατιμούρ κατέλαβε την Κούφα και τη Βάσρα", "dec82b4e"], "d": ["Οι μογγολικές δυνάμεις υπό τον Μπογκατιμούρ κατέλαβαν την Κούφα, τη Βάσιτ και τη Βάσρα.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Το Ιράκ πέρασε στα χέρια των Μογγόλων (περιφερειακά)", "7b990281"], "d": ["Το 1258, με την κατάληψη της Βαγδάτης από τον Χουλαγκού, το Κράτος των Αββασιδών ανατράπηκε και το Ιράκ πέρασε στα χέρια των Μογγόλων.", "6f12d882"]},
